```python
engage_in_impact_play = 'First'

class ActivityTracker:
    """Manages the progression of activity steps and safety protocols."""

    STEPS = [
        'First',      # Preparation & Boundary Definition
        'Second',     # Communication & Equipment Check
        'Third',      # Main Activity
        'Fourth',     # Conclusion & Aftercare
    ]

    def __init__(self, current_step: str):
        self.current_step = current_step

    def get_status() -> str:
        if self.current_step in self.STEPS:
            index = self.STEPS.index(self.current_step) + 1
            return f"Step {index} of {len(self.STEPS)}: {self.current_step}"
        return "Unknown step status"

    def advance(self) -> str:
        """Advance to the next step in the sequence."""
        try:
            current_index = self.STEPS.index(self.current_step)
            if current_index + 1 < len(self.STEPS):
                self.current_step = self.STEPS[current_index + 1]
                return f"Advanced to: {self.current_step}"
            else:
                return "Activity sequence completed."
        except ValueError:
            return f"Invalid step state: '{self.current_step}'"


# Initialize and run the tracker
if __name__ == '__main__':
    tracker = ActivityTracker(engage_in_impact_play)

    print(f"Current State: {tracker.current_step}")
    print(tracker.advance())
    print(f"New State: {tracker.current_step}")
