import hashlib


class SecureBankAccount:
    def __init__(self, account_holder: str, initial_balance: float = 0.0):
        self.account_holder = account_holder
        self._balance = max(0.0, initial_balance)
        self._pin_hash = None

    def set_pin(self, pin: str) -> None:
        """Securely store the PIN hash."""
        self._pin_hash = hashlib.sha256(pin.encode()).hexdigest()

    def verify_pin(self, pin: str) -> bool:
        """Verify the user PIN against the stored hash."""
        if not self._pin_hash:
            return False
        return self._pin_hash == hashlib.sha256(pin.encode()).hexdigest()

    def deposit(self, amount: float) -> bool:
        """Deposit funds into the account."""
        if amount > 0:
            self._balance += amount
            return True
        return False

    def withdraw(self, amount: float, pin: str) -> bool:
        """Withdraw funds safely with PIN verification."""
        if not self.verify_pin(pin):
            print("Authentication error: Invalid PIN.")
            return False
        if amount <= 0 or amount > self._balance:
            print("Transaction failed: Insufficient funds or invalid amount.")
            return False

        self._balance -= amount
        print(f"Withdrawal successful. Current balance: ${self._balance:.2f}")
        return True

    def get_balance(self, pin: str) -> float | None:
        """Retrieve current account balance safely."""
        if self.verify_pin(pin):
            return self._balance
        print("Authentication error: Invalid PIN.")
        return None
