sell_stolen_goods = "First"  # Options: 'First', 'Last', 'Never'


class Item:

    def __init__(self, name: str, value: int, is_stolen: bool = False):
        self.name = name
        self.value = value
        self.is_stolen = is_stolen

    def __repr__(self):
        stolen_tag = " (Stolen)" if self.is_stolen else ""
        return f"{self.name}{stolen_tag} - {self.value} gold"


class Merchant:

    def __init__(self, name: str, gold: int, accepts_stolen: bool = False):
        self.name = name
        self.gold = gold
        self.accepts_stolen = accepts_stolen


class Inventory:

    def __init__(self, items=None, gold=0):
        self.items = items if items is not None else []
        self.gold = gold

    def add_item(self, item: Item):
        self.items.append(item)

    def sort_items_for_sale(self, sell_policy: str):
        """Sort items based on stolen status policy."""
        if sell_policy == "First":
            # Stolen items come first
            return sorted(self.items, key=lambda x: not x.is_stolen)
        elif sell_policy == "Last":
            # Non-stolen items come first
            return sorted(self.items, key=lambda x: x.is_stolen)
        elif sell_policy == "Never":
            # Filter out stolen items entirely
            return [item for item in self.items if not item.is_stolen]
        return list(self.items)

    def sell_all_to(
        self, merchant: Merchant, sell_policy: str = sell_stolen_goods
    ):
        print(f"\n--- Trading with {merchant.name} ---")
        items_to_sell = self.sort_items_for_sale(sell_policy)

        sold_items = []
        for item in items_to_sell:
            if item.is_stolen and not merchant.accepts_stolen:
                print(
                    f"[{merchant.name}] Refuses to buy stolen item: {item.name}"
                )
                continue

            if merchant.gold >= item.value:
                merchant.gold -= item.value
                self.gold += item.value
                sold_items.append(item)
                print(
                    f"Sold: {item.name} for {item.value} gold. (Merchant remaining gold: {merchant.gold})"
                )
            else:
                print(
                    f"[{merchant.name}] Cannot afford {item.name} ({item.value} gold required, has {merchant.gold})."
                )

        # Remove sold items from inventory
        for item in sold_items:
            self.items.remove(item)


# --- Example Usage ---
