    player_inventory = Inventory(
        items=[
            Item("Iron Sword", value=20, is_stolen=False),
            Item("Golden Goblet", value=50, is_stolen=True),
            Item("Leather Armor", value=15, is_stolen=False),
            Item("Ruby Necklace", value=100, is_stolen=True),
        ],
